r = wrangler(["deploy", "--dry-run", "--outdir", "out2"]);
if (r.status === 0 || !r.out.includes('"concurrency.limit" field must be a positive integer')) fail("concurrency.limit 0 was not rejected", r.out);
console.log("OK: workflows[].concurrency.limit is validated");

